static void settle(void){uint64_t end=em_cpu.vdp.frames+180;do{step();}while(busy()&&em_cpu.vdp.frames<end);check(!busy(),"intent finishes within original map callbacks");}
static void frames(unsigned n){uint64_t end=em_cpu.vdp.frames+n;while(em_cpu.vdp.frames<end)step();}
static void reset(void){em_cpu=fixture;em_cpu.rom=rom_data;em_cpu.rom_size=sizeof rom_data;em_cpu.reason=NULL;em_cpu.fault=0;em_cpu.audio_mode=AUDIO_MUTE;em_cpu.audio.fm=NULL;memset(em_cpu.pad_buttons,0,sizeof em_cpu.pad_buttons);memset(&em_host,0,sizeof em_host);em_host.dune_mouse.enabled=1;dune_web_selection_reset();native_a=native_b=0;}
static void select_at(int x,int y){before=em_cpu;check(em_web_select_world(x,y),"typed SELECT accepted");check(!memcmp(&before,&em_cpu,sizeof em_cpu),"SELECT queue mutates zero native bytes");settle();}
static void raw_at(int x,int y){check(em_web_world_intent_queue(&em_host.dune_mouse,&em_cpu,x,y),"legacy contextual A queued");settle();}
static void coord(EmWebActionContext c,int*x,int*y){unsigned t;check(em_web_typed_tile(c,&t),"real native occupancy exists");*x=(t&63)*32+16;*y=(t/64)*32+16;}
static EmWebActionContext second_unit(void){for(unsigned i=0;i<102;i++){EmWebActionContext c=em_web_typed_context(0xff1000+i*140,1);unsigned t;if(c.kind&&c.id!=37&&c.owner==dune_word(&em_cpu,0xc274)&&em_web_typed_tile(c,&t))return c;}check(0,"second real own unit");return (EmWebActionContext){0};}
